{"policy":"permit (
    principal,
    action == Action::"readNamespaceSecret",
    resource is NamespaceSecret
)
when {
    (principal is User || principal is ServiceAccount) &&
    principal.clearance >= resource.sensitivity &&
    (
        (principal is User && resource has ownerUser && resource.ownerUser == principal) ||
        (principal is ServiceAccount && resource has ownerServiceAccount && resource.ownerServiceAccount == principal)
    ) &&
    context.currentTime.lessThan(context.serviceAccountToken.expiresAt)
};

forbid (
    principal,
    action == Action::"readNamespaceSecret",
    resource is NamespaceSecret
)
when {
    (principal is User || principal is ServiceAccount) &&
    principal.clearance < resource.sensitivity
};

forbid (
    principal,
    action == Action::"readNamespaceSecret",
    resource is NamespaceSecret
)
when {
    (principal is User || principal is ServiceAccount) &&
    !(
        (principal is User && resource has ownerUser && resource.ownerUser == principal) ||
        (principal is ServiceAccount && resource has ownerServiceAccount && resource.ownerServiceAccount == principal)
    )
};

forbid (
    principal,
    action == Action::"readNamespaceSecret",
    resource is NamespaceSecret
)
when {
    (principal is User || principal is ServiceAccount) &&
    context.currentTime.greaterThanOrEqual(context.serviceAccountToken.expiresAt)
};"}
